/* Base styles for elderly-friendly readability */
html {
  font-size: 18px;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  line-height: 1.6;
}

/* Focus styles for accessibility */
*:focus-visible {
  outline: 3px solid var(--color-primary-500);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Print styles for Emergency Card */
@media print {
  .no-print {
    display: none !important;
  }

  .print-only {
    display: block !important;
  }

  body {
    font-size: 14px;
    background: white;
    color: black;
  }
}

/* Record type badge colors */
@utility badge-prescription {
  background-color: #dbeafe;
  color: #1e40af;
}

@utility badge-lab-report {
  background-color: #f3e8ff;
  color: #6b21a8;
}

@utility badge-diagnosis {
  background-color: #fee2e2;
